// Keyword mine over a local corpus
const fs = require('fs');
const src = '$param:corpus_path';
const kws = '$param:keywords'.split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
let hits = {};
let sample = [];
if (fs.existsSync(src) && kws.length) {
  const lines = fs.readFileSync(src, 'utf8').split('\n');
  for (const line of lines) {
    const low = line.toLowerCase();
    for (const kw of kws) {
      if (low.includes(kw)) {
        hits[kw] = (hits[kw] || 0) + 1;
        if (sample.length < 5 && !sample.includes(line)) sample.push(line.slice(0, 110));
      }
    }
  }
}
const summary = Object.entries(hits).map(([k, v]) => `• **${k}**: ${v}`).join('\n') || '_no matches_';
const content = `⛏️ **Keyword mine** (${new Date().toISOString().slice(0,10)})\n${summary}${sample.length ? '\n\nTop lines:\n' + sample.map(s => '> ' + s).join('\n') : ''}`;
return [{ json: { content } }];
